const G=HelpDesignGeometry,key='helpdesign-icon-designer-v1';
let state={...G.defaults};try{const saved=JSON.parse(localStorage.getItem(key));if(saved)for(const k in state)if(typeof saved[k]===typeof state[k])state[k]=saved[k];}catch{}
const specs=[['radius','外圆角',4.5,10,.05,'frame'],['width','边框粗细',1,6,.05,'frame'],['x','水平位置',10,42,.05,'pen'],['y','垂直位置',20,58,.05,'pen'],['scale','大小',.4,1.4,.01,'pen'],['angle','角度',-85,-5,.5,'pen'],['tip','笔尖圆弧',0,2,.05,'pen'],['shoulder','笔身过渡',0,6,.05,'pen']];
const $=id=>document.getElementById(id);
for(const [id,label,min,max,step,group]of specs){const row=document.createElement('div');row.className='control';row.innerHTML=`<div class="control-top"><label for="${id}-number">${label}</label><input id="${id}-number" type="number" min="${min}" max="${max}" step="${step}"></div><input id="${id}-range" aria-label="${label}滑块" type="range" min="${min}" max="${max}" step="${step}">`;$(group+'-controls').append(row);for(const suffix of ['number','range'])$(id+'-'+suffix).addEventListener('input',e=>{if(e.target.value===''||!Number.isFinite(e.target.valueAsNumber))return;state[id]=e.target.valueAsNumber;if(id==='width')state.radius=Math.max(state.radius,state.width+.5);if(id==='radius')state.width=Math.min(state.width,state.radius-.5);render();});}
function normalize(){for(const [id,,min,max]of specs)state[id]=Math.min(max,Math.max(min,Number.isFinite(state[id])?state[id]:G.defaults[id]));state.width=Math.min(state.width,state.radius-.5);if(state.lock)state.y=48;}
function render(){normalize();const g=G.geometry(state);$('frame').setAttribute('d',g.frame);$('pen').setAttribute('d',g.pen);for(const [id]of specs)for(const suffix of ['number','range']){const input=$(id+'-'+suffix);input.value=Number(state[id].toFixed(2));input.disabled=id==='y'&&state.lock;}$('lock').checked=state.lock;$('alignment').textContent=state.lock?'底边已齐平 · Y 48.00':'自由位置 · Y '+state.y.toFixed(2);$('samples').innerHTML=[16,24,32,48].map(size=>`<div class="sample">${G.svg(state).replace('width="512" height="512"',`width="${size}" height="${size}"`)}${size} px</div>`).join('');try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
$('lock').addEventListener('change',e=>{state.lock=e.target.checked;render();});$('guides').addEventListener('change',e=>$('guide-lines').style.display=e.target.checked?'':'none');$('reset').onclick=()=>{state={...G.defaults};render();toast('已恢复初始参数');};
let timer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),2200);}
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([G.svg(state)],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='HelpDesign.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('SVG 已导出');};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(G.svg(state));toast('SVG 已复制');}catch{$('svg-text').value=G.svg(state);$('copy-dialog').showModal();$('svg-text').focus();$('svg-text').select();}};$('close-dialog').onclick=()=>$('copy-dialog').close();
let drag;function position(e){return new DOMPoint(e.clientX,e.clientY).matrixTransform($('preview').getScreenCTM().inverse());}
$('pen').addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=position(e);drag={id:e.pointerId,p,x:state.x,y:state.y};$('pen').setPointerCapture(e.pointerId);e.preventDefault();});$('pen').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=position(e);state.x=drag.x+p.x-drag.p.x;if(!state.lock)state.y=drag.y+p.y-drag.p.y;render();});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('pen').addEventListener(type,()=>drag=null);
render();
